impl Module {
    pub fn count_records(&self, counts: &mut ListCounts) {
        counts[ProgramList::ModuleRequests as usize] += self.requests.len() as u64;
        counts[ProgramList::ModuleExports as usize] += self.exports.len() as u64;
        counts[ProgramList::SyntheticExports as usize] += self.synthetic_exports.len() as u64;
        counts[ProgramList::RequiredNames as usize] += self.required_names.len() as u64;
        self.positions.count_records(counts);
        counts[ProgramList::Bytes as usize] += self.function_text.len() as u64;
    }
    pub fn write_record<'a>(&'a self, sections: &mut SectionWriter<'a>, record: &mut Vec<u32>) {
        record.extend([
            self.path.to_word(), self.display_path.to_word(), self.kind.to_wire(), self.flags.0, self.export_rule.to_wire(), self.require_result.to_wire(),
            self.external_kind.to_wire(), self.runtime_module.map_or(ABSENT_WORD, RuntimeModule::to_wire), optional_id_to_word(self.referrer),
            optional_id_to_word(self.body), optional_id_to_word(self.exports_variable), optional_id_to_word(self.data)
        ]);
        {
            let mut element_words = Vec::with_capacity(self.requests.len() * 5);
            for element in &self.requests { element.write_record(sections, &mut element_words); }
            let span = sections.push_records(ProgramList::ModuleRequests, &element_words, self.requests.len());
            record.extend([span.first, span.count]);
        }
        {
            let mut element_words = Vec::with_capacity(self.exports.len() * 7);
            for element in &self.exports { element.write_record(sections, &mut element_words); }
            let span = sections.push_records(ProgramList::ModuleExports, &element_words, self.exports.len());
            record.extend([span.first, span.count]);
        }
        {
            let mut element_words = Vec::with_capacity(self.synthetic_exports.len() * 3);
            for element in &self.synthetic_exports { element.write_record(sections, &mut element_words); }
            let span = sections.push_records(ProgramList::SyntheticExports, &element_words, self.synthetic_exports.len());
            record.extend([span.first, span.count]);
        }
        {
            let mut element_words = Vec::with_capacity(self.required_names.len() * 3);
            for element in &self.required_names { element.write_record(sections, &mut element_words); }
            let span = sections.push_records(ProgramList::RequiredNames, &element_words, self.required_names.len());
            record.extend([span.first, span.count]);
        }
        self.positions.write_record(sections, record);
        {
            let span = sections.push_bytes(&self.function_text);
            record.extend([span.first, span.count]);
        }
    }
}

