impl DataNode {
    pub fn count_records(&self, counts: &mut ListCounts) {
        match self {
            DataNode::Undefined => {}
            DataNode::Null => {}
            DataNode::Hole => {}
            DataNode::Boolean { .. } => {}
            DataNode::Number { .. } => {}
            DataNode::String { .. } => {}
            DataNode::BigInt { .. } => {}
            DataNode::Array { elements, .. } => {
                counts[ProgramList::DataNodes as usize] += elements.len() as u64;
                for element in elements { element.count_records(counts); }
            }
            DataNode::Object { members, .. } => {
                counts[ProgramList::DataMembers as usize] += members.len() as u64;
                for element in members { element.count_records(counts); }
            }
        }
    }
    pub fn write_record<'a>(&'a self, sections: &mut SectionWriter<'a>, record: &mut Vec<u32>) {
        match self {
            DataNode::Undefined => {
                record.push(0);
                record.extend([0; 3]);
            }
            DataNode::Null => {
                record.push(1);
                record.extend([0; 3]);
            }
            DataNode::Hole => {
                record.push(2);
                record.extend([0; 3]);
            }
            DataNode::Boolean { value } => {
                record.push(3);
                record.push(u32::from(*value));
                record.extend([0; 2]);
            }
            DataNode::Number { value } => {
                record.push(4);
                record.extend([value.to_bits() as u32, (value.to_bits() >> 32) as u32]);
                record.extend([0; 1]);
            }
            DataNode::String { value } => {
                record.push(5);
                record.push(value.to_word());
                record.extend([0; 2]);
            }
            DataNode::BigInt { digits } => {
                record.push(6);
                record.push(digits.to_word());
                record.extend([0; 2]);
            }
            DataNode::Array { contents, elements } => {
                record.push(7);
                record.push(contents.to_word());
                {
                    let mut element_words = Vec::with_capacity(elements.len() * 4);
                    for element in elements { element.write_record(sections, &mut element_words); }
                    let span = sections.push_records(ProgramList::DataNodes, &element_words, elements.len());
                    record.extend([span.first, span.count]);
                }
            }
            DataNode::Object { layout, members } => {
                record.push(8);
                record.push(layout.to_word());
                {
                    let mut element_words = Vec::with_capacity(members.len() * 5);
                    for element in members { element.write_record(sections, &mut element_words); }
                    let span = sections.push_records(ProgramList::DataMembers, &element_words, members.len());
                    record.extend([span.first, span.count]);
                }
            }
        }
    }
}

